import { Component, Emit, Prop, Vue } from 'vue-property-decorator';
import { IOperatorTheme } from '@game-studio/operator-theme';
import { OverlaysEventEmitter } from '../../event-emitter';
import { OPTIONS } from '../../options';

@Component({
    name: 'TimeKeeper'
})
export default class TimeKeeper extends Vue {
    @Prop({
        required: true,
        type: String
    })
    public username: string;

    @Prop({
        required: false,
        type: Object,
        default: () => OPTIONS.theme
    })
    public theme: IOperatorTheme;
    public isVisible: boolean = false;
    public title: string = '';
    public text: string = '';

    // Computed properties with guards for optional theme fields
    get headingColor(): string {
        return this.theme.textColour?.heading?.string ?? this.theme.darkAccent.string;
    }

    get bodyColor(): string {
        return this.theme.textColour?.body?.string ?? '#000000';
    }

    get primaryButtonStyle(): Record<string, string> {
        const shadowColor = this.theme.primaryButton?.boxShadowColour?.string;
        return {
            backgroundColor: this.theme.primaryButton?.backgroundColour?.string ?? this.theme.darkAccent.string,
            color: this.theme.primaryButton?.textColour?.string ?? '#FFFFFF',
            borderColor: this.theme.primaryButton?.outlineColour?.string ?? this.theme.darkAccent.string,
            boxShadow: shadowColor ? `0 4px 0 ${shadowColor}` : 'none'
        };
    }

    get secondaryButtonStyle(): Record<string, string> {
        const shadowColor = this.theme.secondaryButton?.boxShadowColour?.string;
        return {
            backgroundColor: this.theme.secondaryButton?.backgroundColour?.string ?? '#FFFFFF',
            color: this.theme.secondaryButton?.textColour?.string ?? this.theme.darkAccent.string,
            borderColor: this.theme.secondaryButton?.outlineColour?.string ?? this.theme.darkAccent.string,
            boxShadow: shadowColor ? `0 4px 0 ${shadowColor}` : 'none'
        };
    }

    get tertiaryButtonStyle(): Record<string, string> {
        const shadowColor = this.theme.tertiaryButton?.boxShadowColour?.string;
        return {
            backgroundColor: this.theme.tertiaryButton?.backgroundColour?.string ?? '#FFFFFF',
            color: this.theme.tertiaryButton?.textColour?.string ?? this.theme.darkAccent.string,
            borderColor: this.theme.tertiaryButton?.outlineColour?.string ?? 'none',
            boxShadow: shadowColor ? `0 4px 0 ${shadowColor}` : 'none'
        };
    }

    public created() {
        this.show = this.show.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showTimeKeeper', this.show);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showTimeKeeper', this.show);
    }

    public show(limit: number) {
        const unit = limit < 3600 ? 'minute' : 'hour';
        const duration = limit < 3600 ? limit / 60 : limit / 3600;

        this.title = 'Time Keeper';
        this.text = `Hi ${this.username}, you've exceeded your ${duration} ${unit} time limit.`;
        this.isVisible = true;
    }

    @Emit('onContinue')
    public onContinue() {
        this.hide();
    }

    @Emit('onClose')
    public onClose() {
        this.hide();
    }

    @Emit('onTransactions')
    public onTransactions() {
        this.hide();
    }

    private hide() {
        this.isVisible = false;
    }
}
